Function pair <- JsonPair(name As String, stock As Integer)
  Define pair As String;
  pair <- '"' + name + '": ' + toText(stock);
EndFunction

Algorithm TwoPairs
  Define leftName As String;
  Define firstStock As Integer;
  Define rightName As String;
  Define secondStock As Integer;
  Read leftName;
  Read firstStock;
  Read rightName;
  Read secondStock;
  Write "{", JsonPair(leftName, firstStock), ", ", JsonPair(rightName, secondStock), "}";
EndAlgorithm
